// Generates the project and component types and standalone validators from the JSON schemas.
//
//   npm run schema:gen     write src/project/generated and src/parts/generated
//   npm run schema:check   regenerate in memory, fail if a committed file differs, then validate every example
//
// When a schema changes: run `npm run schema:gen`, review the diff of the generated files, and commit them
// with the schema. Never edit the generated files by hand. Ajv and json-schema-to-typescript are pinned
// exactly in package.json because their output is part of the committed bytes (spike AX-B2-01).
import { createHash } from 'node:crypto';
import { createRequire } from 'node:module';
import { mkdirSync, mkdtempSync, readFileSync, readdirSync, existsSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { gzipSync } from 'node:zlib';
import Ajv2020 from 'ajv/dist/2020.js';
import standaloneCode from 'ajv/dist/standalone/index.js';
import { compile } from 'json-schema-to-typescript';

const SCHEMA_DIR = 'docs/MASTER_PLAN/04_ARCHITECTURE/schemas';
export const AJV_MODULE = 'ajv/dist/2020.js';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(import.meta.url);
const HEADER = 'Generated by scripts/schema-gen.mjs. Do not edit.';

const PROJECT_VALIDATORS = {
  validateProject: '',
  validateOp: '#/$defs/Op',
  validateOpEnvelope: '#/$defs/OpEnvelope',
  validateProposal: '#/$defs/Proposal',
  validateReplayLog: '#/$defs/ReplayLog',
  validateFileEnvelope: '#/$defs/FileEnvelope',
  validateSimulation: '#/$defs/Simulation',
  validateDomains: '#/$defs/Domains',
  validateFrame: '#/$defs/Frame',
  validateBody: '#/$defs/Body',
  validateJoint: '#/$defs/Joint',
  validateMount: '#/$defs/Mount',
  validateBoard: '#/$defs/Board',
  validateComponent: '#/$defs/Component',
};
const COMPONENT_VALIDATORS = { validateComponent: '' };

const TARGETS = [
  {
    dir: 'src/project/generated',
    schema: 'project.schema.json',
    domains: ['robotics.domain.schema.json', 'drone.domain.schema.json'],
    rootType: 'Project',
    ajv: {},
    validators: PROJECT_VALIDATORS,
  },
  {
    dir: 'src/parts/generated',
    schema: 'component.schema.json',
    domains: [],
    rootType: 'Component',
    ajv: { allowUnionTypes: true },
    validators: COMPONENT_VALIDATORS,
  },
];

const BASE_AJV = { strict: true, inlineRefs: false, strictRequired: false, allErrors: true, code: { source: true, esm: true } };

const readSchema = (name) => readFileSync(join(root, SCHEMA_DIR, name), 'utf8');
const sha256 = (text) => createHash('sha256').update(text).digest('hex');

// Ajv writes its three runtime helpers as require() calls, which do not exist in an ES module.
function inlineRuntime(src) {
  return src.replace(/require\("ajv\/dist\/runtime\/(\w+)"\)\.default/g, (_, name) => `(${require(`ajv/dist/runtime/${name}`).default.toString()})`);
}

function validatorModule(target) {
  const ajv = new Ajv2020({ ...BASE_AJV, ...target.ajv });
  for (const name of target.domains) ajv.addSchema(JSON.parse(readSchema(name)));
  const schema = JSON.parse(readSchema(target.schema));
  ajv.addSchema(schema);
  const refs = Object.fromEntries(Object.entries(target.validators).map(([name, path]) => [name, schema.$id + path]));
  const source = inlineRuntime(standaloneCode(ajv, refs));
  return `// ${HEADER}\n${source}`;
}

// Type names come from the $defs keys, so the human titles are dropped before the type generator sees them.
function withoutTitles(node) {
  if (Array.isArray(node)) return node.map(withoutTitles);
  if (node === null || typeof node !== 'object') return node;
  return Object.fromEntries(
    Object.entries(node)
      .filter(([key, value]) => !(key === 'title' && typeof value === 'string'))
      .map(([key, value]) => [key, withoutTitles(value)]),
  );
}

async function typesModule(target) {
  const domainText = Object.fromEntries(
    target.domains.map((name) => {
      const text = readSchema(name);
      return [JSON.parse(text).$id, text];
    }),
  );
  const body = await compile({ ...withoutTitles(JSON.parse(readSchema(target.schema))), title: target.rootType }, target.rootType, {
    cwd: join(root, SCHEMA_DIR),
    additionalProperties: false,
    unreachableDefinitions: true,
    format: true,
    bannerComment: '',
    enableConstEnums: false,
    strictIndexSignatures: true,
    maxItems: -1,
    $refOptions: {
      resolve: { urn: { order: 1, canRead: /^urn:/, read: (file) => domainText[file.url.replace(/#.*/, '')] } },
    },
  });
  const hashes = [target.schema, ...target.domains].map((name) => `  '${name}': '${sha256(readSchema(name))}',`);
  return `// ${HEADER}\n\nexport const GENERATED_FROM = {\n${hashes.join('\n')}\n} as const;\n\n${body}`;
}

function declarations(target) {
  const lines = [
    `// ${HEADER}`,
    '',
    'export interface SchemaError {',
    '  instancePath: string;',
    '  schemaPath: string;',
    '  keyword: string;',
    '  message?: string;',
    '  params: Record<string, unknown>;',
    '}',
    '',
    'export interface Validator<T = unknown> {',
    '  (data: unknown): data is T;',
    '  errors: SchemaError[] | null;',
    '}',
    '',
  ];
  for (const name of Object.keys(target.validators)) {
    const type = name.replace(/^validate/, '');
    lines.push(`export const ${name}: Validator<import('./types.ts').${type}>;`);
  }
  return `${lines.join('\n')}\n`;
}

export async function generate() {
  const files = new Map();
  for (const target of TARGETS) {
    files.set(`${target.dir}/types.ts`, await typesModule(target));
    files.set(`${target.dir}/validate.mjs`, validatorModule(target));
    files.set(`${target.dir}/validate.d.mts`, declarations(target));
  }
  return files;
}

export function writeAll(files) {
  for (const [path, text] of files) {
    mkdirSync(dirname(join(root, path)), { recursive: true });
    writeFileSync(join(root, path), text);
    console.log(`${path}  ${Buffer.byteLength(text)} bytes, ${gzipSync(text).length} gzip`);
  }
}

export function checkAll(files) {
  return [...files]
    .filter(([path, text]) => !existsSync(join(root, path)) || readFileSync(join(root, path), 'utf8') !== text)
    .map(([path]) => path);
}

const listJson = (dir, suffix) =>
  existsSync(dir) ? readdirSync(dir).filter((name) => name.endsWith(suffix)).sort().map((name) => join(dir, name)) : [];

export async function validateExamples(files) {
  const scratch = mkdtempSync(join(tmpdir(), 'schema-gen-'));
  try {
    const load = async (target) => {
      const file = join(scratch, `${target.rootType}.mjs`);
      writeFileSync(file, files.get(`${target.dir}/validate.mjs`));
      return import(pathToFileURL(file).href);
    };
    const [project, component] = await Promise.all(TARGETS.map(load));
    const examples = join(root, SCHEMA_DIR, 'examples');
    const jobs = [
      ...listJson(examples, '.project.json').map((file) => [file, project.validateProject]),
      ...listJson(join(examples, 'components'), '.component.json').map((file) => [file, component.validateComponent]),
      ...listJson(join(root, 'src/parts/data'), '.component.json').map((file) => [file, component.validateComponent]),
    ];
    return jobs.flatMap(([file, validate]) => {
      if (validate(JSON.parse(readFileSync(file, 'utf8')))) return [];
      const first = validate.errors[0];
      return [`${file.slice(root.length + 1)}: ${first.instancePath || '/'} ${first.message}`];
    });
  } finally {
    rmSync(scratch, { recursive: true, force: true });
  }
}

export async function main(argv) {
  const files = await generate();
  if (!argv.includes('--check')) {
    writeAll(files);
    return 0;
  }
  const stale = checkAll(files);
  for (const path of stale) console.error(`stale: ${path}`);
  if (stale.length > 0) console.error('Run `npm run schema:gen` and commit the result.');
  const invalid = await validateExamples(files);
  for (const line of invalid) console.error(`invalid example: ${line}`);
  return stale.length + invalid.length === 0 ? 0 : 1;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  process.exitCode = await main(process.argv.slice(2));
}
